using MediLabX.Native.Models;
using System.Windows;
using System.Windows.Controls;
namespace MediLabX.Native;
public partial class MainWindow {
 private FrameworkElement Daily(){var root=Column();var date=Today;var header=Row();var input=Field(header,"Date (yyyy-MM-dd)",Today);root.Children.Add(Card(header,"Daily summary"));var sum=Column();var list=Column();root.Children.Add(Card(sum));root.Children.Add(Card(list,"Patient-wise visits"));
  void reload(){sum.Children.Clear();list.Children.Clear();date=input.Text;var p=store.All<Patient>("patients").Where(x=>!x.Deleted&&x.Date==date).ToList();var e=store.All<Expense>("expenses").Where(x=>x.Date==date).ToList();sum.Children.Add(Text($"Patients: {p.Count}     Gross: Rs {p.Sum(x=>x.Subtotal):N0}     Net: Rs {p.Sum(x=>x.Net):N0}     Received: Rs {p.Sum(x=>x.Received):N0}     Expenses: Rs {e.Sum(x=>x.Amount):N0}     Balance: Rs {p.Sum(x=>x.Balance):N0}",14,true));list.Children.Add(GridView(p.Select(x=>new{x.Receipt,x.Name,x.Mr,Tests=string.Join(", ",x.Tests.Select(t=>t.Name)),x.Net,x.Received,x.Balance}).ToList(),345));}input.TextChanged+=(_,_)=>reload();reload();return root;
 }
 private FrameworkElement Expenses(){var root=Column();var panel=Column();var date=Field(panel,"Date",Today);var description=Field(panel,"Description");var amount=Field(panel,"Amount (Rs)","0");panel.Children.Add(Action("Add expense",()=>{if(string.IsNullOrWhiteSpace(description.Text)||Dec(amount.Text)<=0){Info("Enter a description and positive amount.");return;}var x=new Expense{Date=date.Text,Description=description.Text,Amount=Dec(amount.Text),CreatedBy=current?.UserName??""};SaveAndRefresh("expenses",x.Id,x,"Expense saved.");},true));root.Children.Add(Card(panel,"Expenses"));var data=store.All<Expense>("expenses").OrderByDescending(x=>x.Date).ToList();var grid=GridView(data.Select(x=>new{x.Date,x.Description,x.Amount,x.CreatedBy,Record=x}).ToList(),360);root.Children.Add(Card(grid,$"Recorded expenses — Rs {data.Sum(x=>x.Amount):N0}"));var actions=Row();actions.Children.Add(Action("Edit selected",()=>{if(grid.SelectedItem is null)return;var x=(Expense)grid.SelectedItem.GetType().GetProperty("Record")!.GetValue(grid.SelectedItem)!;date.Text=x.Date;description.Text=x.Description;amount.Text=x.Amount.ToString();panel.Children.Add(Action("Save edited expense",()=>{x.Date=date.Text;x.Description=description.Text;x.Amount=Dec(amount.Text);SaveAndRefresh("expenses",x.Id,x,"Expense updated.");},true));}));actions.Children.Add(Action("Delete selected",()=>{if(current?.Role!="Admin"){Info("Admin access required.");return;}if(grid.SelectedItem is null)return;var x=(Expense)grid.SelectedItem.GetType().GetProperty("Record")!.GetValue(grid.SelectedItem)!;if(MessageBox.Show("Delete selected expense?","MediLab X",MessageBoxButton.YesNo)==MessageBoxResult.Yes){store.Delete("expenses",x.Id);OpenPage(page);}}));root.Children.Add(Card(actions));return root;
 }
 private FrameworkElement Earnings(){var root=Column();var patients=store.All<Patient>("patients").Where(x=>!x.Deleted).ToList();var expense=store.All<Expense>("expenses");var grid=new System.Windows.Controls.Primitives.UniformGrid{Columns=4};foreach(var (label,n) in new[]{("Gross billed",patients.Sum(x=>x.Subtotal)),("Discounts",patients.Sum(x=>x.Discount)),("Received",patients.Sum(x=>x.Received)),("Cash after expenses",patients.Sum(x=>x.Received)-expense.Sum(x=>x.Amount))}){var sp=Column();sp.Children.Add(Text(label,11,true));sp.Children.Add(Text("Rs "+n.ToString("N0"),23,true));grid.Children.Add(Card(sp));}root.Children.Add(grid);
  var filters=Row();var from=Field(filters,"From",DateTime.Today.AddDays(-30).ToString("yyyy-MM-dd"));var to=Field(filters,"To",Today);root.Children.Add(Card(filters,"Patient-wise earning records"));var details=Column();root.Children.Add(Card(details));void update(){details.Children.Clear();var matched=patients.Where(x=>string.CompareOrdinal(x.Date,from.Text)>=0&&string.CompareOrdinal(x.Date,to.Text)<=0).OrderByDescending(x=>x.Date);details.Children.Add(GridView(matched.Select(x=>new{x.Date,x.Receipt,Patient=x.Name,x.Mr,Procedure=string.Join(", ",x.Tests.Select(t=>t.Name)),x.Subtotal,x.Discount,x.Net,x.Received,x.Balance}).ToList(),420));}from.TextChanged+=(_,_)=>update();to.TextChanged+=(_,_)=>update();update();return root;
 }
 private FrameworkElement Rates(){var root=Column();var tests=store.All<TestDefinition>("tests").OrderBy(x=>x.Name).ToList();var form=Row();var search=Field(form,"Search test");var price=Field(form,"Updated price (Rs)");root.Children.Add(Card(form,"Radiology rate list"));var grid=new DataGrid{Height=440,ItemsSource=tests,IsReadOnly=true,AutoGenerateColumns=true};root.Children.Add(Card(grid));
  void filter()=>grid.ItemsSource=tests.Where(x=>x.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).ToList();search.TextChanged+=(_,_)=>filter();var buttons=Row();buttons.Children.Add(Action("Update selected price",()=>{if(current?.Role!="Admin"){Info("Admin only.");return;}if(grid.SelectedItem is not TestDefinition t||Dec(price.Text)<0)return;t.Price=Dec(price.Text);store.Put("tests",t.Id,t);OpenPage(page);},true));root.Children.Add(Card(buttons));return root;
 }
 private FrameworkElement Laboratory(){var root=Column();var form=Column();var kit=Field(form,"Kit name *");var company=Field(form,"Company");var lot=Field(form,"Lot number *");var supplier=Field(form,"Received from");var received=Field(form,"Received date",Today);var expiry=Field(form,"Expiry date (yyyy-MM-dd)");var quantity=Field(form,"Received stock quantity","1");form.Children.Add(Action("Receive reagent batch",()=>{if(string.IsNullOrWhiteSpace(kit.Text)||string.IsNullOrWhiteSpace(lot.Text)||Dec(quantity.Text)<=0){Info("Kit name, lot number and positive quantity required.");return;}var b=new Reagent{KitName=kit.Text,Company=company.Text,LotNo=lot.Text,ReceivedFrom=supplier.Text,ReceivedDate=received.Text,Expiry=expiry.Text,ReceivedQuantity=Dec(quantity.Text),Quantity=Dec(quantity.Text)};b.History.Add(new StockMove{Kind="Received",Quantity=b.Quantity,Note="Initial stock"});SaveAndRefresh("reagents",b.Id,b,"Reagent batch received.");},true));root.Children.Add(Card(form,"Reagent records"));var all=store.All<Reagent>("reagents");var view=GridView(all.Select(x=>new{x.KitName,x.Company,x.LotNo,x.ReceivedFrom,x.ReceivedDate,x.Expiry,x.Quantity,x.Finished,Record=x}).ToList(),340);root.Children.Add(Card(view,"Active and historical stock"));var action=Row();var movement=Field(action,"Quantity", "1");root.Children.Add(Card(action));
  Reagent? selected()=>view.SelectedItem is null?null:(Reagent?)view.SelectedItem.GetType().GetProperty("Record")?.GetValue(view.SelectedItem);
  var buttons=Row();buttons.Children.Add(Action("Issue stock",()=>{var b=selected();var q=Dec(movement.Text);if(b is null||b.Finished||q<=0||q>b.Quantity){Info("Select active stock and enter a quantity not exceeding remaining stock.");return;}b.Quantity-=q;b.History.Add(new StockMove{Kind="Issued",Quantity=-q});store.Put("reagents",b.Id,b);OpenPage(page);}));buttons.Children.Add(Action("Restock",()=>{var b=selected();var q=Dec(movement.Text);if(b is null||q<=0)return;b.Quantity+=q;b.Finished=false;b.History.Add(new StockMove{Kind="Restocked",Quantity=q});store.Put("reagents",b.Id,b);OpenPage(page);}));buttons.Children.Add(Action("Mark finished",()=>{var b=selected();if(b is null)return;b.History.Add(new StockMove{Kind="Finished",Quantity=-b.Quantity,Note="Manual stock closure"});b.Quantity=0;b.Finished=true;store.Put("reagents",b.Id,b);OpenPage(page);}));buttons.Children.Add(Action("Movement history",()=>{var b=selected();if(b is not null)Info(string.Join("\n",b.History.Select(x=>$"{x.Date}  {x.Kind}: {x.Quantity}  {x.Note}")));}));root.Children.Add(Card(buttons));return root;
 }
}